<script setup lang="ts">const platform = usePlatformApi(); const search = ref(''); const topic = ref(''); const level = ref('all'); const sort = ref('desc'); const { data: tasks, pending, error, refresh: reload } = await useAsyncData('catalog-tasks', () => platform.listTasks()); const refresh = () => reload(); const topics = computed(() => [...new Set((tasks.value || []).map(task => task.card.topic).filter(Boolean))]); const filtered = computed(() => { const q = search.value.trim().toLowerCase(); const result = (tasks.value || []).filter(task => (!topic.value || task.card.topic === topic.value) && (level.value === 'all' || task.score.level === level.value) && (!q || Object.values(task.card).join(' ').toLowerCase().includes(q))); return result.sort((a,b) => sort.value === 'asc' ? a.score.total-b.score.total : sort.value === 'new' ? Date.parse(b.createdAt)-Date.parse(a.createdAt) : b.score.total-a.score.total); }); useHead({ title: 'Каталог задач — Мост' });</script>
<template><div class="page"><div class="page-heading"><div><h1>Задачи, которые ждут <span>вас.</span></h1><p>Настоящие вызовы бизнеса.</p></div></div><div class="catalog-toolbar"><label class="search-field"><input v-model="search" type="search" placeholder="Поиск" aria-label="Поиск задач"></label><label class="select-field"><select v-model="topic" aria-label="Тема задачи"><option value="">Все темы</option><option v-for="item in topics" :key="item">{{ item }}</option></select></label><label class="select-field"><select v-model="level" aria-label="Уровень готовности"><option value="all">Любая готовность</option><option value="draft">draft</option><option value="workable">workable</option><option value="ready">ready</option><option value="priority">priority</option></select></label><label class="select-field"><select v-model="sort" aria-label="Сортировка задач"><option value="desc">Сначала готовые</option><option value="asc">Сначала требующие деталей</option><option value="new">Сначала новые</option></select></label></div><p v-if="pending">Загружаем каталог…</p><p v-else-if="error" class="error-text">Не удалось загрузить каталог. <button @click="refresh">Повторить</button></p><div v-else-if="filtered.length" class="task-grid"><TaskCard v-for="task in filtered" :key="task.id" :task="task" /></div><EmptyState v-else title="Пока ничего не нашлось" description="Измените фильтры поиска." /></div></template>
